#!/usr/bin/env bash
# Generate ~/.codex/AGENTS.md from the shared, model-agnostic AI rules that
# Claude's CLAUDE.md also @imports, so both agents read one copy.
# Edit the sources cat'd below, never the generated file.
set -euo pipefail

dotfiles="${DOTFILES_HOME:-$HOME/.dotfiles}"
out="$HOME/.codex/AGENTS.md"
mkdir -p "$HOME/.codex"

{
  printf '<!-- GENERATED by ~/.dotfiles/codex/build-agents.sh. Edit the sources, not this file. -->\n\n'
  cat "$dotfiles/ai-rules/global-working-rules.md"
  printf '\n\n'
  cat "$dotfiles/ai-rules/git-signing.md"
  printf '\n\n'
  cat "$dotfiles/ai-rules/documentation-context-closure.md"
  printf '\n'
} > "$out.tmp"

mv "$out.tmp" "$out"
echo "wrote $out ($(wc -c < "$out") bytes)"
